def plain_reply(text,intent):
 text=text.replace('**','')
 text=re.sub(r'(?m)^\s*#{1,6}\s*','',text)
 if intent!='recommend':
  text=re.sub(r'[^。\n！？!?]*[？?]','',text)
 return text.strip()

def split_products(text,products):
 matches=list(re.finditer(r'\[\[(商品:(\d+)|总结)\]\]',text))
 if not matches:return text,{}
 allowed={p['id'] for p in products};notes={};general=[text[:matches[0].start()].strip()]
 for i,m in enumerate(matches):
  content=text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)].strip()
  if m.group(1)=='总结':general.append(content)
  elif int(m.group(2)) in allowed:notes[str(int(m.group(2)))]=content
 return '\n\n'.join(t for t in general if t),notes

def question_key(text):
 t=re.sub(r'[^\w]','',text.lower())
 for word in ('请','帮我','一下','的','呢','吗'):t=t.replace(word,'')
 return t

def related_questions(intent,text,history):
 bank={
  'recommend':['有没有更轻的款式','预算提高一点还有哪些选择','想看不同风格的备选','哪款收纳更方便','这几款的主要不足分别是什么','推荐适合短途旅行的款式'],
  'analysis':['这款主要的缺点是什么','这款适合每天带电脑吗','推荐几款用途相近的','这款和另一款的差异在哪里','它的容量适合短途出行吗','这款适合什么穿搭'],
  'compare':['哪款更适合我的日常','按轻便程度再选一款','想看看其他备选','这几款各自的主要不足是什么','优先电脑保护应该选哪款','适合周末出行的是哪款'],
  'chat':['帮我选个背包','分析一款商品','比较两款背包','看看适合日常通勤的款式']}
 originals=[question_key(text)]+[question_key(m['content']) for m in history[-5:] if m['role']=='user']
 result=[]
 for candidate in bank[intent]:
  key=question_key(candidate)
  if any(key==q or len(q)>=5 and (key in q or q in key or difflib.SequenceMatcher(None,key,q).ratio()>=0.84) for q in originals):continue
  result.append(candidate)
  if len(result)==3:break
 return result

